    @Test void requiredCoreReadFailureStillEscapesInsteadOfReturningMissingEvidence(){requiredReadFailure("QC_FACT_OCCURRENCE WHERE");}
    @Test void requiredBatchReadFailureStillEscapesInsteadOfReturningMissingEvidence(){requiredReadFailure("QC_RECORD WHERE ID");}
    void requiredReadFailure(String sql){cn.bidcheck.domain.Domain.Document d=doc(1);publish(d,batch(cn.bidcheck.compat.Java8Api.listOf(fact("f","等级0",cn.bidcheck.compat.Java8Api.listOf("A"))),cn.bidcheck.compat.Java8Api.listOf(source(d,1,"A")),"one"));cn.bidcheck.verification.facts.FactLedgerService.PreparedManifest manifest=candidate.prepareManifest("project","engine",cn.bidcheck.compat.Java8Api.listOf(d));java.util.Map<java.lang.String, java.lang.Object> req=cn.bidcheck.compat.Java8Api.<String, Object>mapOf("sourceIds", cn.bidcheck.compat.Java8Api.listOf("A"), "includeFieldCoverage", true);statements.failSql=sql;
        session.clearCache();RuntimeException before=assertThrows(RuntimeException.class,()->original.lookup("project","engine",cn.bidcheck.compat.Java8Api.listOf(d),req));assertTrue(messageChain(before).contains("SYNTHETIC_REQUIRED_READ_FAILED"));
        session.clearCache();RuntimeException after=assertThrows(RuntimeException.class,()->candidate.lookup(manifest,req));assertTrue(messageChain(after).contains("SYNTHETIC_REQUIRED_READ_FAILED"));statements.failSql="";
        assertEquals(1,compare(d,req).result().size(),"After the database recovers, required evidence is still available; a failure did not persist absence.");
    }
    String messageChain(Throwable error){StringBuilder out=new StringBuilder();for(Throwable cause=error;cause!=null;cause=cause.getCause())out.append(cause.getMessage()).append(' ');return out.toString();}
    Map<String,Long> hist(List<String> sql){Map<String,Long> out=new TreeMap<>();for(String s:sql)out.merge(s,1L,Long::sum);return out;}
    void write(String file,Object value)throws Exception {String folder=System.getProperty("lookup.replay.output");if(folder==null)return;Path out=java.nio.file.Paths.get(folder);Files.createDirectories(out);json.writerWithDefaultPrettyPrinter().writeValue(out.resolve(file).toFile(),value);}
